using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Analysis;

internal sealed class NormalL1RealizationDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "A positive complex-linear continuous-function map with normal unit value and scalar mass measure has a positive, mass-preserving, contractive normal-valued realization on the entire complex L1 space.",
        H("Entire complex L1 realization"),
        Blocks(Describe.Lean(
            DescribeId.Create("exists-normal-l1-extension"),
            DeclarationHandle.Create("D5/S3/Quantum/Analysis/NormalL1Realization.exists_normal_L1_extension"),
            H("The positive normal whole-L1 extension"),
            StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("A is any unital complex C-star algebra with a partial order and StarOrderedRing compatibility. K is any compact metric Borel space. The measure nu is finite and weakly regular. J is an actual complex-linear map from C(K,C) to the continuous complex dual of A. For every pointwise nonnegative continuous g and every positive a in A, J(g)(a)>=0. The functional J(1) is order-normal in the all-directed sense of NormalFunctionals.IsOrderNormal. For every complex continuous g, J(g)(1)=integral g dnu. No continuity of J, support condition, nonzero total mass, nontriviality of A, finite dimension or chosen predual is assumed. Normality of all J(g) is derived from normality of J(1), so in particular the theorem applies when all values are given normal.")),
                Paragraph(Text("There exists a continuous complex-linear map Gamma from the entire complex L1(nu) to StrongDual C A. It agrees exactly with J on ContinuousMap.toLp 1 nu C g for every continuous complex g. Every Gamma(h) is order-normal. For every L1 class h that is nonnegative almost everywhere, Gamma(h)(a)>=0 for every positive a. For every complex L1 class h, Gamma(h)(1)=integral h dnu. Its actual operator norm is at most one. Positivity, mass and normality hold for all L1 inputs in their stated domains, rather than only bounded, simple or positive source inputs.")),
                Paragraph(Text("For positive continuous g, 0<=J(g)<=||g||J(1), and domination gives normality. Decomposition into positive and negative parts of the real and imaginary components then gives normality for every complex g. The same decomposition and the exact Mathlib identity for the norm of a positive functional give ||J(g)||<=2 integral ||g|| dnu=2||toLp(g)||. LinearMap.extendOfNorm factors through the null kernel of toLp and extends the map directly into the complete closed normalDual submodule. Thus vanishing mass on an open set, the zero measure and the zero algebra need no separate support or injectivity argument.")),
                Paragraph(Text("Positive continuous L1 classes are dense in the almost-everywhere positive cone: approximate a positive h by continuous complex g and replace g pointwise by ofReal(max(Re(g),0)). Projection onto the positive real ray decreases the distance to each positive complex number, hence decreases the L1 error. Closedness of positive scalar evaluations passes positivity to Gamma(h). Continuity and ContinuousMap.toLp_denseRange pass the scalar mass identity to every complex L1 class.")),
                Paragraph(Text("For a measurable set E, positivity and mass give ||Gamma(1_E)||=nu(E). Complex linearity therefore bounds Gamma(c 1_E) by its L1 norm for every complex c. On disjoint simple pieces the input L1 norms add, while output norms satisfy the triangle inequality. The existing Mathlib Lp.induction principle and closedness of the norm inequality extend this sharp bound to all complex L1 classes, proving ||Gamma||<=1. The initial constant two is only used for construction.")),
                Paragraph(Text("For the posterior consumer take K=Set.Icc (0 : ℝ) 1. Exact continuous source expressions are p : C(K, ℂ) := ⟨fun t => (t.val : ℂ), by fun_prop⟩ and q : C(K, ℂ) := 1 - p. If e=ContinuousMap.toLp 1 nu ℂ, the agreement clause yields Gamma(e p)=J p and Gamma(e q)=J q; linearity also gives e q=e 1-e p. Both source classes are nonnegative, and zero total mass is included. These are the actual posterior moments, with no normalized-state or full-support hypothesis.")),
                Paragraph(Text("The theorem starts with an actual scalar mass measure and does not construct that measure by Riesz representation. Full arbitrary-von-Neumann attainment still requires a compact compatible moment family, construction and uniqueness of its scalar Riesz measures, exact comparison with every original whole-complex-L1 reverse test, extended lower semicontinuity and a minimum including the +infinity branch. No chosen-predual identification, RNP, vector density or operator-convex assumption is introduced. These missing global steps and the normal-predual equivalence are outside this theorem.")),
                Paragraph(Text("The source reuses Mathlib's positive-functional norm identity, continuous-function density, LinearMap.extendOfNorm and existing simple-function Lp induction. It does not construct a vector measure or a second L1 completion. This is a supporting realization theorem for the full attainment problem; it is not a solution of that problem or a claim of new literature priority."))
            ), DescribeRole.Theorem))));
}
